import json
H=W=30
g=[[0]*W for _ in range(H)]
starts=[1,8,15,22,29]
rowstarts=[1,8,15,22,29]
# Fill 5x5 framed tiles; the last row/column are clipped by the grid boundary.
patterns={
  0:[3,2,2,3,0],
  1:[2,8,8,2,0],
  2:[3,2,2,3,0],
  3:[2,8,8,2,0],
  4:[0,0,0,0,0],
}
for tr,rs in enumerate(rowstarts):
  for tc,cs in enumerate(starts):
    if rs>=H or cs>=W: continue
    val=patterns[tr][tc]
    for dr in range(5):
      r=rs+dr
      if r>=H: continue
      for dc in range(5):
        c=cs+dc
        if c>=W: continue
        g[r][c]= (val if 1<=dr<=3 and 1<=dc<=3 else 4)
# Connect same-color marked tiles horizontally and vertically through separator gutters.
for color, positions in [(3,[(0,0),(0,3),(2,0),(2,3)]),(8,[(1,1),(1,2),(3,1),(3,2)])]:
  byrow={}
  bycol={}
  for tr,tc in positions:
    byrow.setdefault(tr,[]).append(tc)
    bycol.setdefault(tc,[]).append(tr)
  for tr,cols in byrow.items():
    cols=sorted(cols)
    for a,b in zip(cols,cols[1:]):
      rs=rowstarts[tr]
      for c in range(starts[a]+5,starts[b]):
        for r in range(rs+1,rs+4): g[r][c]=color
  for tc,rows in bycol.items():
    rows=sorted(rows)
    for a,b in zip(rows,rows[1:]):
      cs=starts[tc]
      for r in range(rowstarts[a]+5,rowstarts[b]):
        for c in range(cs+1,cs+4): g[r][c]=color
print(json.dumps(g,separators=(',',':')))

import json
n=30
out=[[0]*n for _ in range(n)]
starts=[1,8,15,22]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Recreate the given tiled input exactly: 5x5 tiles, 4 border, 3x3 centers.
for ti,r in enumerate(starts):
 for tj,c in enumerate(starts):
  v=colors[ti][tj]
  for dr in range(5):
   for dc in range(5):
    out[r+dr][c+dc]=v if 1<=dr<=3 and 1<=dc<=3 else 4
# Special center colors extend through the immediately adjacent two-cell gutters.
for ti,r in enumerate(starts):
 for tj,c in enumerate(starts):
  v=colors[ti][tj]
  if v==2: continue
  # Horizontal extensions, preserving the center's three-row span.
  for rr in range(r+1,r+4):
   for cc in range(c-2,c):
    if 0<=cc<n: out[rr][cc]=v
   for cc in range(c+5,c+7):
    if 0<=cc<n: out[rr][cc]=v
  # Vertical extensions, preserving the center's three-column span.
  for cc in range(c+1,c+4):
   for rr in range(r-2,r):
    if 0<=rr<n: out[rr][cc]=v
   for rr in range(r+5,r+7):
    if 0<=rr<n: out[rr][cc]=v
# Last row/column are the visible top/left edge of the next tile, as in the input.
for c in starts:
 out[29][c:c+5]=[4]*min(5,n-c)
for r in starts:
 for rr in range(r,min(r+5,n)):
  out[rr][29]=4
out[29][29]=4
assert len(out)==30 and all(len(row)==30 for row in out)
print(json.dumps(out,separators=(',',':')))

import json
n=30
out=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
centers=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# reconstruct tile pattern including the clipped fifth row/column border
for ti,r0 in enumerate(starts):
 for tj,c0 in enumerate(starts):
  v=centers[ti][tj] if ti<4 and tj<4 else None
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     out[r][c] = (v if v is not None and 1<=dr<=3 and 1<=dc<=3 else 4)
# Join all matching marked tiles in each aligned row/column by coloring only the intervening zero gutters.
# horizontal
for ti,vals in enumerate(centers):
 r0=starts[ti]
 for color in (3,8):
  cols=[tj for tj,v in enumerate(vals) if v==color]
  if len(cols)>=2:
   for a,b in zip(cols,cols[1:]):
    for tj in range(a,b):
     for r in range(r0+1,r0+4):
      for c in range(starts[tj]+5,starts[tj+1]):
       if out[r][c]==0: out[r][c]=color
# vertical
for tj in range(4):
 for color in (3,8):
  rows=[ti for ti in range(4) if centers[ti][tj]==color]
  if len(rows)>=2:
   for a,b in zip(rows,rows[1:]):
    for ti in range(a,b):
     for r in range(starts[ti]+5,starts[ti+1]):
      for c in range(starts[tj]+1,starts[tj]+4):
       if out[r][c]==0: out[r][c]=color
print(json.dumps(out,separators=(',',':')))

